1	import type { Course } from "@/schema/course"
2	import type { Day, Interval } from "@/schema/schedule"
3	import type { AssignedFull, Field, PreselectFull } from "@/types/course-table"
4	import { fields } from "@/types/course-table"
5	
6	export type Time = `${Day}${Interval}`
7	
8	type TimeCourse = {
9	  id: string
10	  field: Field
11	  times: Time[]
12	}
13	
14	export const getTimesUrl = (course?: Course | null) => {
15	  if (!course) return []
16	  const times = course.schedules.flatMap((schedule) =>
17	    schedule.intervals.map<Time>((interval) => `${schedule.weekday}${interval}`)
18	  )
19	  return times
20	}
21	
22	export const getPreselectMap = (courses: PreselectFull[]) => {
23	  const timeMap: { [key in Time]?: TimeCourse[] } = {}
24	  const courseMap: { [key: string]: Course & { field?: Field } } = {}
25	  courses.forEach(({ serial, course, field }) => {
26	    const times = getTimesUrl(course)
27	    const id = `${course.semester}-${serial}`
28	    courseMap[id] = { ...course, field: fields[field!] }
29	    times.forEach((time) => {
30	      if (!timeMap[time]) timeMap[time] = []
31	      timeMap[time]!.push({
32	        id,
33	        field: fields[field!],
34	        times: times,
35	      })
36	    })
37	  })
38	  return { timeMap, courseMap }
39	}
40	
41	export const getAssignedMap = (courses: AssignedFull[]) => {
42	  const assignedMap: {
43	    [key in Time]?: (AssignedFull & { location: string })[]
44	  } = {}
45	  courses.forEach(({ serial, course }) => {
46	    course.schedules.forEach((schedule) => {
47	      schedule.intervals.forEach((interval) => {
48	        const time = `${schedule.weekday}${interval}` as Time
49	        if (!assignedMap[time]) assignedMap[time] = []
50	        assignedMap[time]!.push({
51	          serial,
52	          course,
53	          location: schedule.classroom?.name || "",
54	        })
55	      })
56	    })
57	  })
58	  return assignedMap
59	}
